import Anthropic from "@anthropic-ai/sdk";
import { tools } from "./definitions";
import { executeToolWithPolicy } from "./interceptor";

const client = new Anthropic();

export async function runAgentLoop(
  userMessage: string,
  history: Anthropic.MessageParam[] = []
): Promise<Anthropic.MessageParam[]> {
  const messages: Anthropic.MessageParam[] = [
    ...history,
    { role: "user", content: userMessage },
  ];

  const MAX_ITERATIONS = 8; // salvaguarda contra loops descontrolados
  let iterations = 0;

  while (iterations < MAX_ITERATIONS) {
    iterations++;

    const response = await client.messages.create({
      model: "claude-sonnet-4-5",
      max_tokens: 2048,
      system: SYSTEM_PROMPT,
      tools,
      messages,
    });

    messages.push({ role: "assistant", content: response.content });

    if (response.stop_reason === "end_turn") {
      // El modelo decidió que no necesita más herramientas: fin del loop.
      return messages;
    }

    if (response.stop_reason === "tool_use") {
      const toolUseBlocks = response.content.filter(
        (b): b is Anthropic.ToolUseBlock => b.type === "tool_use"
      );

      const toolResults = await Promise.all(
        toolUseBlocks.map(async (block) => {
          const result = await executeToolWithPolicy(block.name, block.input);
          return {
            type: "tool_result" as const,
            tool_use_id: block.id,
            content: JSON.stringify(result.payload),
            is_error: result.isError,
          };
        })
      );

      messages.push({ role: "user", content: toolResults });
      continue; // vuelve a llamar al modelo con los resultados
    }

    // stop_reason === 'max_tokens' u otro: no hay más que hacer de forma segura.
    throw new Error(`Stop reason inesperado: ${response.stop_reason}`);
  }

  throw new Error("Se alcanzó MAX_ITERATIONS sin llegar a end_turn");
}

const SYSTEM_PROMPT = `Sos un agente de soporte al cliente. Descomponé
solicitudes con múltiples pedidos en sub-tareas independientes, resolvé cada
uma con la herramienta correspondiente, y sintetizá una única respuesta al
final. Nunca inventes el resultado de una herramienta.`;

export type ErrorCategory = "transient" | "validation" | "permission";

export interface StructuredToolError {
  errorCategory: ErrorCategory;
  isRetryable: boolean;
  message: string;
}

export function buildError(
  category: ErrorCategory,
  message: string
): StructuredToolError {
  return {
    errorCategory: category,
    isRetryable: category === "transient",
    message,
  };
}

// Ejemplos de uso dentro de una herramienta:

// 1) Transient — el modelo puede reintentar sin cambiar el input.
// buildError('transient', 'Timeout al conectar con el gateway de pagos. Reintentá en unos segundos.')

// 2) Validation — el modelo debe corregir el input, no reintentar igual.
// buildError('validation', "order_id 'ORD-9' no tiene el formato esperado ORD-XXXXXX.")

// 3) Permission — no hay reintento posible; la única salida es escalar.
// buildError('permission', 'El monto de reembolso excede el límite autorizado para este canal. Usá escalate_to_human.')

import { buildError } from "./errors";

const REFUND_ESCALATION_THRESHOLD_USD = 500;

interface ToolExecutionResult {
  payload: unknown;
  isError: boolean;
}

// Se ejecuta ANTES de la herramienta real. Si retorna un resultado,
// ese resultado reemplaza la ejecución — la herramienta real nunca corre.
function applyBusinessRules(
  toolName: string,
  input: any
): ToolExecutionResult | null {
  if (toolName === "process_refund") {
    const order = lookupOrderAmount(input.order_id); // acceso a datos reales, no confía en el input del modelo
    if (order.amount_usd > REFUND_ESCALATION_THRESHOLD_USD) {
      return {
        isError: true,
        payload: buildError(
          "permission",
          `Reembolso de $${order.amount_usd} excede el umbral autorizado de ` +
            `$${REFUND_ESCALATION_THRESHOLD_USD}. No reintentar process_refund para esta ` +
            `orden — usá escalate_to_human con el detalle del caso.`
        ),
      };
    }
  }
  return null; // ninguna regla se disparó: seguir con la ejecución normal
}

export async function executeToolWithPolicy(
  toolName: string,
  input: any
): Promise<ToolExecutionResult> {
  const blocked = applyBusinessRules(toolName, input);
  if (blocked) return blocked;

  try {
    const payload = await dispatchToRealTool(toolName, input);
    return { payload, isError: false };
  } catch (e) {
    return { payload: buildError("transient", String(e)), isError: true };
  }
}

