from pydantic import BaseModel, Field
from typing import Literal, Optional

class Party(BaseModel):
    name: str
    role: Literal["landlord", "tenant", "buyer", "seller", "other"]
    role_detail: Optional[str] = Field(
        None, description="Obligatorio si role='other'. Descripción libre del rol."
    )

class ContractExtraction(BaseModel):
    # Requeridos: todo contrato, por definición, tiene partes y un tipo.
    parties: list[Party]
    contract_type: Literal["lease", "purchase", "service", "nda", "other"]
    contract_type_detail: Optional[str] = Field(
        None, description="Obligatorio si contract_type='other'."
    )

    # Nullable: pueden legítimamente no aparecer en el documento fuente.
    termination_date: Optional[str] = Field(
        None, description="Fecha de terminación en ISO 8601, o null si el contrato no la especifica (indefinido)."
    )
    penalty_clause_amount_usd: Optional[float] = Field(
        None, description="Monto de penalidad por incumplimiento, o null si el contrato no define ninguna."
    )
    governing_law: Optional[str] = Field(
        None, description="Jurisdicción aplicable, o null si el documento no la menciona."
    )

tool_schema = {
    "name": "extract_contract",
    "description": "Extrae los campos estructurados de un contrato. Usar null explícito para cualquier campo cuya información no esté presente en el documento — nunca inferir o inventar un valor plausible.",
    "input_schema": ContractExtraction.model_json_schema(),
}

import anthropic
import time

client = anthropic.Anthropic()

def submit_batch(documents: dict[str, str]) -> str:
    requests = [
        {
            "custom_id": doc_id,
            "params": {
                "model": "claude-sonnet-4-5",
                "max_tokens": 2048,
                "tools": [tool_schema],
                "tool_choice": {"type": "tool", "name": "extract_contract"},
                "messages": [{"role": "user", "content": f"Extraé:\n\n{text}"}],
            },
        }
        for doc_id, text in documents.items()
    ]
    batch = client.messages.batches.create(requests=requests)
    return batch.id

def collect_results(batch_id: str, sla_minutes: int = 60) -> dict:
    started = time.monotonic()
    while True:
        batch = client.messages.batches.retrieve(batch_id)
        if batch.processing_status == "ended":
            break
        time.sleep(15)

    elapsed_min = (time.monotonic() - started) / 60
    if elapsed_min > sla_minutes:
        alert_sla_breach(batch_id, elapsed_min, sla_minutes)

    results, failed_ids = {}, []
    for entry in client.messages.batches.results(batch_id):
        if entry.result.type == "succeeded":
            results[entry.custom_id] = entry.result.message
        else:
            failed_ids.append((entry.custom_id, entry.result.type))

    return {"results": results, "failed": failed_ids, "elapsed_minutes": elapsed_min}

def resubmit_failed(failed_ids: list[str], documents: dict[str, str]) -> str:
    # Ej. errored_type='invalid_request' por exceder el límite de contexto:
    # se reenvían truncados/chunkeados, no se reintentan idénticos.
    chunked = {
        doc_id: chunk_document(documents[doc_id], max_tokens=150_000)
        for doc_id in failed_ids
    }
    return submit_batch(chunked)

from pydantic import BaseModel

class FieldConfidence(BaseModel):
    value: str | float | None
    confidence: float  # 0.0–1.0, el modelo lo autoevalúa por campo

CONFIDENCE_THRESHOLD = 0.75

def route_for_review(extraction: dict, doc_id: str, doc_type: str) -> list[str]:
    low_confidence_fields = [
        field for field, data in extraction.items()
        if isinstance(data, dict) and data.get("confidence", 1.0) < CONFIDENCE_THRESHOLD
    ]
    if low_confidence_fields:
        enqueue_human_review(doc_id, doc_type, fields=low_confidence_fields)
    return low_confidence_fields

def accuracy_by_segment(labeled_results: list[dict]) -> dict:
    """labeled_results: extracciones ya validadas contra ground truth,
    con doc_type y, por campo, si coincidió o no."""
    from collections import defaultdict
    stats = defaultdict(lambda: defaultdict(lambda: [0, 0]))  # [aciertos, total]

    for row in labeled_results:
        for field, correct in row["field_matches"].items():
            bucket = stats[row["doc_type"]][field]
            bucket[1] += 1
            bucket[0] += int(correct)

    return {
        doc_type: {f: hits / total for f, (hits, total) in fields.items()}
        for doc_type, fields in stats.items()
    }

