import { query, type AgentDefinition } from "@anthropic-ai/claude-agent-sdk";

const webResearchAgent: AgentDefinition = {
  description: "Busca información actual en la web sobre un tema puntual y devuelve hallazgos con fuente y fecha",
  tools: ["WebSearch", "WebFetch"],
  prompt: WEB_RESEARCH_SYSTEM_PROMPT, // ver Paso 3: exige el formato estructurado de hallazgo
  model: "sonnet",
};

const documentAnalysisAgent: AgentDefinition = {
  description: "Analiza documentos internos (PDFs, reportes) ya provistos y extrae hallazgos relevantes a una pregunta",
  tools: ["Read", "Grep"],
  prompt: DOCUMENT_ANALYSIS_SYSTEM_PROMPT,
  model: "sonnet",
};

export async function runCoordinator(researchQuestion: string) {
  for await (const message of query({
    prompt: buildCoordinatorPrompt(researchQuestion),
    options: {
      allowedTools: ["Task"], // el coordinador SOLO delega, no investiga por sí mismo
      agents: {
        "web-research": webResearchAgent,
        "document-analysis": documentAnalysisAgent,
      },
    },
  })) {
    handleCoordinatorMessage(message);
  }
}

function buildCoordinatorPrompt(question: string): string {
  return `Pregunta de investigación: "${question}"

Delegá esta pregunta a los subagentes relevantes. Para cada invocación de
Task, incluí en el prompt del subagente el contexto específico que necesita
(la sub-pregunta puntual, no la pregunta completa sin acotar) — los
subagentes NO heredan esta conversación, solo reciben lo que les pasás
explícitamente en el prompt de Task.`;
}

// Prompt del coordinador que induce paralelismo cuando corresponde:
const COORDINATOR_SYSTEM_PROMPT = `Cuando una pregunta de investigación se
descompone en sub-preguntas independientes (ninguna necesita el resultado de
otra para empezar), emitilas TODAS como llamadas a Task en la misma
respuesta — no esperes el resultado de una para lanzar la siguiente. Si una
sub-pregunta sí depende del resultado de otra, ejecutalas en el orden
necesario.`;

// Medición de la mejora de latencia (harness de benchmark, no código de
// producción):
async function benchmarkParallelVsSequential(question: string) {
  const t0 = performance.now();
  await runCoordinator(question); // coordinador con prompt de arriba -> paralelo
  const parallelMs = performance.now() - t0;

  const t1 = performance.now();
  await runSequentialBaseline(question); // variante forzada a un Task por vez
  const sequentialMs = performance.now() - t1;

  return { parallelMs, sequentialMs, speedup: sequentialMs / parallelMs };
}

// Resultado típico con 2 subagentes de ~20s cada uno:
// secuencial: ~40s (20s + 20s en serie)
// paralelo:   ~22s (ambos corren a la vez, domina el más lento + overhead)
// speedup: ~1.8x

interface Finding {
  claim: string;             // la afirmación en sí
  evidence_excerpt: string;  // cita textual que la sostiene, no un resumen
  source: string;            // URL o identificador exacto del documento
  published_date: string | null; // ISO 8601, o null si la fuente no la declara
}

const WEB_RESEARCH_SYSTEM_PROMPT = `Investigá la sub-pregunta asignada usando
WebSearch y WebFetch. Devolvé cada hallazgo como un objeto con exactamente
estos campos: claim, evidence_excerpt (cita textual, no paráfrasis), source
(URL completa), published_date (ISO 8601 o null si la página no la indica).
No mezcles estos campos en prosa libre — se necesitan separados para que el
subagente de síntesis pueda atribuir cada afirmación a su fuente.`;

// El subagente de síntesis recibe un array de Finding[] de cada subagente,
// nunca resúmenes en texto libre sin estructura:
const SYNTHESIS_SYSTEM_PROMPT = `Recibiste hallazgos estructurados de
múltiples subagentes. Al sintetizar el reporte final, cada afirmación debe
seguir citando su source original entre corchetes, ej: "La tasa de adopción
creció 40% en 2025 [fuente: gartner.com/report-2025]." Nunca combines dos
hallazgos de fuentes distintas en una sola oración sin atribuir cada parte a
su fuente correspondiente.`;

interface SubagentFailure {
  agentId: string;
  failureType: "timeout" | "tool_error" | "empty_result";
  attemptedQuery: string;
  partialResults: Finding[]; // lo que sí alcanzó a recolectar antes de fallar
}

async function runSubagentWithTimeout(
  agentKey: string,
  subQuestion: string,
  timeoutMs = 45_000
): Promise<Finding[] | SubagentFailure> {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);

  try {
    const results = await invokeSubagent(agentKey, subQuestion, controller.signal);
    clearTimeout(timer);
    return results;
  } catch (e) {
    clearTimeout(timer);
    return {
      agentId: agentKey,
      failureType: controller.signal.aborted ? "timeout" : "tool_error",
      attemptedQuery: subQuestion,
      partialResults: extractPartialResults(e), // lo recolectado hasta el fallo
    };
  }
}

function isFailure(r: Finding[] | SubagentFailure): r is SubagentFailure {
  return "failureType" in r;
}

async function synthesizeWithGaps(results: (Finding[] | SubagentFailure)[]) {
  const successful = results.filter((r): r is Finding[] => !isFailure(r)).flat();
  const failures = results.filter(isFailure);

  const report = await synthesize(successful);

  if (failures.length > 0) {
    report.coverageGaps = failures.map(f =>
      `No se pudo completar la investigación de "${f.attemptedQuery}" ` +
      `(${f.failureType}). ${f.partialResults.length > 0
        ? `Se incluyeron ${f.partialResults.length} hallazgos parciales recolectados antes del fallo.`
        : "No se recolectó ningún hallazgo antes del fallo."}`
    );
  }

  return report;
}

const SYNTHESIS_SYSTEM_PROMPT_CONFLICTS = `Al sintetizar hallazgos de
múltiples fuentes:

1. Si dos o más fuentes independientes coinciden en un hecho, presentalo en
   la sección "Hallazgos bien establecidos".
2. Si fuentes creíbles reportan valores DISTINTOS para el mismo hecho
   (ej. una estadística), NO elijas uno arbitrariamente ni promedies los
   valores. Presentalo en la sección "Puntos en disputa", listando cada
   valor con su fuente exacta:
   "La tasa de adopción reportada varía según la fuente: 40% según Gartner
   [gartner.com/...] vs. 28% según Forrester [forrester.com/...]. Posibles
   causas de la discrepancia: metodología de medición o período cubierto
   distintos."
3. Nunca presentes un valor en disputa como si fuera un hecho consolidado
   solo porque apareció primero en los hallazgos recibidos.`;

// Ejemplo de estructura de salida esperada del subagente de síntesis:
interface SynthesisReport {
  establishedFindings: Finding[];         // consenso entre fuentes
  disputedFindings: {
    topic: string;
    values: { claim: string; source: string }[]; // todos los valores en conflicto, sin elegir uno
    note: string; // posible causa de la discrepancia, si es inferible
  }[];
  coverageGaps?: string[]; // del Paso 4
}
